package com.yeyamo_mobile.api.notification_service.application;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import java.time.Instant;import java.util.*;import org.junit.jupiter.api.Test;import org.mockito.ArgumentCaptor;import com.yeyamo_mobile.api.notification_service.application.port.*;import com.yeyamo_mobile.api.notification_service.domain.*;
class DevicePushTokenServiceTest{private static final String TOKEN="ExponentPushToken[test-device-token]";@Test void registersNewDeviceAndEnablesPush(){var devices=mock(DevicePushTokenRepositoryPort.class);var preferences=mock(PreferenceRepositoryPort.class);when(devices.findByToken(TOKEN)).thenReturn(Optional.empty());when(devices.findByUserIdAndDeviceId("u1","device-1")).thenReturn(Optional.empty());when(devices.save(any())).thenAnswer(i->i.getArgument(0));when(preferences.find("u1")).thenReturn(Optional.of(NotificationPreference.defaults("u1",null)));var saved=new DevicePushTokenService(devices,preferences).register("u1",TOKEN,DevicePlatform.ANDROID,"device-1","1.0.0");assertTrue(saved.enabled());assertEquals("device-1",saved.deviceId());ArgumentCaptor<NotificationPreference>preference=ArgumentCaptor.forClass(NotificationPreference.class);verify(preferences).save(preference.capture());assertTrue(preference.getValue().pushEnabled());}@Test void upsertsExistingDeviceAndReactivatesIt(){var devices=mock(DevicePushTokenRepositoryPort.class);var preferences=mock(PreferenceRepositoryPort.class);Instant created=Instant.now().minusSeconds(60);var existing=new DevicePushToken(UUID.randomUUID(),"u1",TOKEN,DevicePlatform.ANDROID,"device-1","0.9",false,created,created,created,created);when(devices.findByToken(TOKEN)).thenReturn(Optional.of(existing));when(devices.findByUserIdAndDeviceId("u1","device-1")).thenReturn(Optional.of(existing));when(devices.save(any())).thenAnswer(i->i.getArgument(0));when(preferences.find("u1")).thenReturn(Optional.of(NotificationPreference.defaults("u1",null)));var saved=new DevicePushTokenService(devices,preferences).register("u1",TOKEN,DevicePlatform.ANDROID,"device-1","1.0");assertTrue(saved.enabled());assertNull(saved.invalidatedAt());assertEquals(created,saved.createdAt());}@Test void unregisterDisablesWithoutDeleting(){var devices=mock(DevicePushTokenRepositoryPort.class);var existing=new DevicePushToken(UUID.randomUUID(),"u1",TOKEN,DevicePlatform.ANDROID,"device-1","1.0",true,Instant.now(),Instant.now(),Instant.now(),null);when(devices.findByUserIdAndDeviceId("u1","device-1")).thenReturn(Optional.of(existing));new DevicePushTokenService(devices,mock(PreferenceRepositoryPort.class)).unregister("u1","device-1");ArgumentCaptor<DevicePushToken>saved=ArgumentCaptor.forClass(DevicePushToken.class);verify(devices).save(saved.capture());assertFalse(saved.getValue().enabled());assertNotNull(saved.getValue().invalidatedAt());}}
